use nupp_vm::{image, interp::Interp, value::Value};

// The large compiler image is generated by the stage-zero driver, not tracked.
#[test]
#[ignore = "requires NUPP_COMPILER_IMAGE and NUPP_LOWERER_IMAGE"]
fn emitted_lowerer_rebuilds_itself() {
    // Cargo runs crate tests from the crate directory. Match the source-root
    // working directory used to emit the reference image's module paths.
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..");
    std::env::set_current_dir(root).unwrap();
    let compiler = std::fs::read_to_string(std::env::var("NUPP_COMPILER_IMAGE").unwrap()).unwrap();
    let emitted = std::fs::read_to_string(std::env::var("NUPP_LOWERER_IMAGE").unwrap()).unwrap();
    let source = std::fs::read_to_string("src/nupp/compiler/vm/lower.nupp").unwrap();
    let mut it = Interp::new();
    image::load(&mut it, &compiler).unwrap();
    let emitted_base = it.funcs.len();
    image::load(&mut it, &emitted).unwrap();
    it.entries.resize(it.funcs.len(), 0);
    it.prepare_threaded();
    it.install_globals();
    // Load the emitted module before the driver. Its require then resolves to
    // this implementation, not the stage-zero copy in the compiler image.
    let lower = it.require("nupp.compiler.vm.lower");
    let key = it.intern("emit");
    let fun = it.index(lower, key);
    let fid = if let Some(fid) = fun.as_func() { fid } else {
        unsafe { (*fun.as_obj().unwrap().as_ptr()).fid() }
    };
    assert!(fid as usize >= emitted_base, "the driver would use the original lowerer");
    let bench = it.require("nupp.bench.emitbench");
    let compile = it.index(bench, key);
    let text = it.heap_new_string(&source);
    let handle = it.register(text);
    let name = it.intern("nupp.compiler.vm.lower");
    let result = it.call_value(compile, &[text, name]);
    assert_eq!(result.len(), 1);
    assert_ne!(result[0], Value::NIL);
    assert_eq!(it.bytes_of(result[0]), emitted.as_bytes(), "the emitted lowerer did not reproduce itself");
    it.release(handle);
}
